    "inlineSchema": "generator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"esm\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  CUSTOMER\n  ADMIN\n}\n\nenum OrderStatus {\n  PENDING\n  PAID\n  SHIPPING\n  COMPLETED\n  CANCELLED\n}\n\nenum PaymentProvider {\n  VNPAY\n  MOMO\n  COD\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  name         String?\n  phone        String?\n  role         Role     @default(CUSTOMER)\n  orders       Order[]\n  reviews      Review[]\n  cart         Cart?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Category {\n  id       String    @id @default(cuid())\n  name     String\n  slug     String    @unique\n  products Product[]\n}\n\nmodel Product {\n  id          String      @id @default(cuid())\n  name        String\n  slug        String      @unique\n  description String?\n  // Giá lưu theo VND (số nguyên) để khớp VNPay/MoMo\n  price       Int\n  salePrice   Int?\n  images      String[]\n  // Thông tin riêng của nến\n  scent       String?\n  waxType     String?\n  burnTime    Int?\n  stock       Int         @default(0)\n  isFeatured  Boolean     @default(false)\n  category    Category?   @relation(fields: [categoryId], references: [id])\n  categoryId  String?\n  cartItems   CartItem[]\n  orderItems  OrderItem[]\n  reviews     Review[]\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n}\n\nmodel Cart {\n  id        String     @id @default(cuid())\n  user      User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId    String     @unique\n  items     CartItem[]\n  updatedAt DateTime   @updatedAt\n}\n\nmodel CartItem {\n  id        String  @id @default(cuid())\n  cart      Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  cartId    String\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n  quantity  Int     @default(1)\n\n  @@unique([cartId, productId])\n}\n\nmodel Order {\n  id              String      @id @default(cuid())\n  code            String      @unique\n  user            User?       @relation(fields: [userId], references: [id])\n  userId          String?\n  status          OrderStatus @default(PENDING)\n  subtotal        Int\n  shippingFee     Int         @default(0)\n  total           Int\n  customerName    String\n  customerEmail   String\n  customerPhone   String\n  shippingAddress String\n  note            String?\n  items           OrderItem[]\n  payments        Payment[]\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n}\n\nmodel OrderItem {\n  id        String  @id @default(cuid())\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId   String\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n  name      String\n  price     Int\n  quantity  Int\n}\n\nmodel Payment {\n  id            String          @id @default(cuid())\n  order         Order           @relation(fields: [orderId], references: [id])\n  orderId       String\n  provider      PaymentProvider\n  status        PaymentStatus   @default(PENDING)\n  amount        Int\n  // Mã giao dịch phía VNPay (vnp_TransactionNo) / MoMo (transId)\n  transactionId String?\n  rawResponse   Json?\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n}\n\nmodel Review {\n  id        String   @id @default(cuid())\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  productId String\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  rating    Int\n  comment   String?\n  createdAt DateTime @default(now())\n}\n\nmodel NewsletterSubscriber {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  createdAt DateTime @default(now())\n}\n",
